const escape = value => String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initial = candidate => escape(Array.from(candidate.name || '?')[0]);
const proximity = candidate => candidate.distanceKm===null?'距离未知':candidate.distanceKm===0?'同一粗略区域':'区域估算约 '+candidate.distanceKm+' km';
export function candidateDetail(candidate) {
  return `<div class="radar-detail"><div class="radar-avatar">${initial(candidate)}</div><h2>${escape(candidate.name)}</h2><p>${escape(candidate.city||'未填写城市')} · ${escape(candidate.age||'未填写年龄')}</p><p>${escape(candidate.statement||'还没有自我介绍')}</p><div class="chips">${candidate.interests.map(i=>`<span class="pill">${escape(i)}</span>`).join('')}</div><div class="notice"><b>O 为什么推荐</b><p>${candidate.reasons.map(escape).join('<br>')}</p><p class="small muted">来自自填资料，匹配不代表身份核验或关系承诺。</p></div><p class="small muted">${escape(candidate.address)}</p><button class="btn" data-action="invite" data-address="${escape(candidate.address)}">发送 Ring 邀请</button></div>`;
}
function card(candidate, expanded) {
  return `<article class="radar-card ${expanded?'expanded':''}"><button class="radar-save" data-action="radar-save" data-address="${escape(candidate.address)}" aria-label="${candidate.saved?'取消收藏':'收藏'} ${escape(candidate.name)}" aria-pressed="${candidate.saved}">${candidate.saved?'♥':'♡'}</button><button class="radar-person" data-action="radar-detail" data-address="${escape(candidate.address)}" aria-label="查看 ${escape(candidate.name)} 的资料"><div class="radar-avatar">${initial(candidate)}</div><h3>${escape(candidate.name)}</h3><p class="small muted">${escape(candidate.city||'未填写城市')} · ${proximity(candidate)}</p></button><div class="chips">${candidate.interests.slice(0,expanded?8:2).map(i=>`<span class="pill">${escape(i)}</span>`).join('')}</div>${expanded?`<p>${candidate.reasons.map(escape).join(' · ')}</p><button class="btn" data-action="invite" data-address="${escape(candidate.address)}">发送邀请</button>`:''}</article>`;
}
export function radarView(state) {
  const radar=state.radar||{total:0,hasLocation:false},filters=state.radarFilters,candidates=state.candidates;
  const preview=candidates.slice(0,3),expanded=state.radarExpanded;
  const stage=state.radarScanning?'scanning':state.radarError?'error':!state.radar?'idle':radar.total?'results':'empty';
  return `<section class="radar-page" aria-labelledby="radar-title"><div class="radar-brand"><span>Consensus Bell</span><span class="radar-status">真实账号推荐 · 非链上认证</span></div><div class="radar-heading"><h1 id="radar-title">Resonance Radar</h1><p>敲响 Bell，让 O 帮你寻找<br>可能与你共鸣的人。</p></div><div class="radar-stage ${stage}" aria-busy="${Boolean(state.radarScanning)}"><div class="radar-orbit orbit-one"></div><div class="radar-orbit orbit-two"></div><div class="radar-orbit orbit-three"></div><div class="radar-sweep"></div><img class="radar-ring" src="/assets/ring-float.webp" width="280" height="280" alt="共鸣戒指">${preview.map((candidate,index)=>`<button class="radar-satellite satellite-${index}" data-action="radar-detail" data-address="${escape(candidate.address)}" aria-label="查看 ${escape(candidate.name)} 的资料">${initial(candidate)}</button>`).join('')}</div><section class="radar-results" aria-label="匹配结果" aria-live="polite"><div class="radar-result-head"><div><h2>${state.radarError?'探测暂时不可用':state.radarScanning?'O 正在寻找共鸣…':radar.total?'发现 '+radar.total+' 位可能共鸣的人':'还没有发现合适的人'}</h2><p class="small muted">${radar.total?'点击资料查看 O 的具体匹配理由。':'试试扩大范围，或先完善自己的兴趣与意向。'}</p></div>${candidates.length>3?`<button class="radar-more" data-action="radar-expand" aria-expanded="${Boolean(expanded)}">${expanded?'收起':'查看全部'}</button>`:''}</div>${state.radarError?`<p role="alert" class="notice">${escape(state.radarError)}</p>`:''}<div class="radar-grid ${expanded?'all-results':''}">${(expanded?candidates:preview).map(c=>card(c,expanded)).join('')}</div>${!candidates.length?'<p class="radar-empty">这里只展示已登录并主动公开资料的真实用户。<br>不会用示例人物填满雷达。</p>':''}${radar.limited?'<p class="small muted">当前显示排名前 100 位，请缩小筛选范围。</p>':''}</section><form class="radar-filters" data-form="radar"><button class="btn radar-cta" type="submit">${state.radarScanning?'正在探测…':'Ring the Bell · 开始探测'}</button><div class="radar-filter-row"><label>城市<input name="city" maxlength="60" value="${escape(filters.city)}" placeholder="不限城市"></label><label>区域范围<select name="radius">${[0,20,50,100,200].map(km=>`<option value="${km}" ${filters.radius===km?'selected':''}>${km?km+' km':'不限距离'}</option>`).join('')}</select></label><label>关系意向<input name="intention" maxlength="60" value="${escape(filters.intention)}" placeholder="不限意向"></label></div></form><div class="radar-location"><button class="btn light compact" data-action="${radar.hasLocation?'radar-revoke-location':'radar-location'}">${radar.hasLocation?'撤回附近定位':'开启附近定位'}</button><button class="btn light compact" data-action="identity">修改我的资料</button></div><p class="small muted radar-disclosure">O 当前按共同兴趣、意向和城市推荐，不承诺匹配成功。附近范围是粗略区域估算，并非精准距离。${state.profile?.discoverable?'你已允许其他登录用户发现你的公开资料。':'你尚未开启公开资料，其他人无法在雷达中发现你。'}</p></section>`;
}
